    end
    # :call-seq:
    #   unescaped -> String
    #
    # Returns the `unescaped` attribute.
    #
    #: () -> String
    def unescaped
      @unescaped
    end

    # :section: Slicing

    # :call-seq:
    #   opening -> String | nil
    #
    # Slice the location of opening_loc from the source.
    #
    #: () -> String?
    def opening
      opening_loc&.slice
    end

    # :call-seq:
    #   content -> String
    #
    # Slice the location of content_loc from the source.
    #
    #: () -> String
    def content
      content_loc.slice
    end

    # :call-seq:
    #   closing -> String | nil
    #
    # Slice the location of closing_loc from the source.
    #
    #: () -> String?
    def closing
      closing_loc&.slice
    end

    # :section:

    #: (untyped other) -> boolish
    def ===(other) # :nodoc:
      other.is_a?(StringNode) &&
        (flags === other.flags) &&
        (opening_loc.nil? == other.opening_loc.nil?) &&
        (content_loc.nil? == other.content_loc.nil?) &&
        (closing_loc.nil? == other.closing_loc.nil?) &&
        (unescaped === other.unescaped)
    end
  end

