    #
    #: (Source source, Integer node_id, Location location, Integer flags, Location keyword_loc, Location? lparen_loc, ArgumentsNode? arguments, Location? rparen_loc) -> void
    def initialize(source, node_id, location, flags, keyword_loc, lparen_loc, arguments, rparen_loc)
      @source = source
      @node_id = node_id
      @location = location
      @flags = flags
      @keyword_loc = keyword_loc
      @lparen_loc = lparen_loc
      @arguments = arguments
      @rparen_loc = rparen_loc
    end

    # ---------
    # :section: Repository
    # Methods related to Relocation.
    # ---------

    # ----------------------------------------------------------------------------------
    # :section: Node Interface
    # These methods are present on all subclasses of Node.
    # Read the [node interface docs](Node.html#node-interface) for more information.
    # ----------------------------------------------------------------------------------

    # See Node.accept.
    #
    #: (_Visitor visitor) -> untyped
    def accept(visitor)
      visitor.visit_yield_node(self)
    end

    # See Node.child_nodes.
    #
    #: () -> Array[node?]
    def child_nodes
      [arguments]
    end

    # See Node.each_child_node.
    #
    #: () -> Enumerator[node, void]
    #: () { (node) -> void } -> void
    def each_child_node(&blk)
      return to_enum(:each_child_node) unless block_given?

      if (arguments = self.arguments); yield arguments; end
    end

    # See Node.compact_child_nodes.
    #
    #: () -> Array[node]
    def compact_child_nodes
      compact = [] #: Array[Prism::node]
      if (arguments = self.arguments); compact << arguments; end
      compact
    end

    # :call-seq:
    #   copy(**fields) -> YieldNode
    #
    # Creates a copy of self with the given fields, using self as the template.
    #
    #: (?node_id: Integer, ?location: Location, ?flags: Integer, ?keyword_loc: Location, ?lparen_loc: Location?, ?arguments: ArgumentsNode?, ?rparen_loc: Location?) -> YieldNode
    def copy(node_id: self.node_id, location: self.location, flags: self.flags, keyword_loc: self.keyword_loc, lparen_loc: self.lparen_loc, arguments: self.arguments, rparen_loc: self.rparen_loc)
      YieldNode.new(source, node_id, location, flags, keyword_loc, lparen_loc, arguments, rparen_loc)
    end

    alias deconstruct child_nodes

    #: (Array[Symbol]? keys) -> Hash[Symbol, untyped]
    def deconstruct_keys(keys) # :nodoc:
      (keys || %i[node_id location keyword_loc lparen_loc arguments rparen_loc keyword lparen rparen]).each_with_object(
        {} #: Hash[Symbol, untyped]
      ) do |key, deconstructed|
        case key
        when :node_id                 then deconstructed[:node_id] = self.node_id
        when :location                then deconstructed[:location] = self.location
        when :keyword_loc             then deconstructed[:keyword_loc] = self.keyword_loc
        when :lparen_loc              then deconstructed[:lparen_loc] = self.lparen_loc
        when :arguments               then deconstructed[:arguments] = self.arguments
        when :rparen_loc              then deconstructed[:rparen_loc] = self.rparen_loc
        when :keyword                 then deconstructed[:keyword] = self.keyword
        when :lparen                  then deconstructed[:lparen] = self.lparen
        when :rparen                  then deconstructed[:rparen] = self.rparen
        end
      end
    end

    # See `Node#type`.
    #
    #: () -> :yield_node
    def type
      :yield_node
    end

    # See `Node.type`.
    #
    #: () -> :yield_node
    def self.type
      :yield_node
    end

    #: () -> String
    def inspect # :nodoc:
      InspectVisitor.compose(self)
    end

    # :section:

    # :category: Locations
    # :call-seq:
    #   keyword_loc -> Location
    #
    # Returns the Location represented by `keyword_loc`.
    #
    #: () -> Location
    def keyword_loc
      location = @keyword_loc
      return location if location.is_a?(Location)
      @keyword_loc = Location.new(source, location >> 32, location & 0xFFFFFFFF)
    end

    # :category: Repository
    # Save the keyword_loc location using the given saved source so that
    # it can be retrieved later.
    #
    #: (_Repository repository) -> Relocation::Entry
    def save_keyword_loc(repository)
      repository.enter(node_id, :keyword_loc)
    end

    # :category: Locations
    # :call-seq:
    #   lparen_loc -> Location | nil
    #
    # Returns the Location represented by `lparen_loc`.
    #
    #: () -> Location?
    def lparen_loc
      location = @lparen_loc
      case location
      when nil
        nil
      when Location
        location
      else
        @lparen_loc = Location.new(source, location >> 32, location & 0xFFFFFFFF)
      end
    end

    # :category: Repository
    # Save the lparen_loc location using the given saved source so that
    # it can be retrieved later.
    #
    #: (_Repository repository) -> Relocation::Entry?
    def save_lparen_loc(repository)
      repository.enter(node_id, :lparen_loc) unless @lparen_loc.nil?
    end
    # :call-seq:
    #   arguments -> ArgumentsNode | nil
    #
    # Returns the `arguments` attribute.
    #
    #: () -> ArgumentsNode?
    def arguments
      @arguments
    end

    # :category: Locations
    # :call-seq:
    #   rparen_loc -> Location | nil
    #
    # Returns the Location represented by `rparen_loc`.
    #
    #: () -> Location?
    def rparen_loc
      location = @rparen_loc
      case location
      when nil
        nil
      when Location
        location
      else
        @rparen_loc = Location.new(source, location >> 32, location & 0xFFFFFFFF)
      end
    end

    # :category: Repository
    # Save the rparen_loc location using the given saved source so that
    # it can be retrieved later.
    #
    #: (_Repository repository) -> Relocation::Entry?
    def save_rparen_loc(repository)
      repository.enter(node_id, :rparen_loc) unless @rparen_loc.nil?
    end
    # :section: Slicing

    # :call-seq:
    #   keyword -> String
    #
    # Slice the location of keyword_loc from the source.
    #
    #: () -> String
    def keyword
      keyword_loc.slice
    end

    # :call-seq:
    #   lparen -> String | nil
    #
    # Slice the location of lparen_loc from the source.
    #
    #: () -> String?
    def lparen
      lparen_loc&.slice
    end

    # :call-seq:
    #   rparen -> String | nil
    #
    # Slice the location of rparen_loc from the source.
    #
    #: () -> String?
    def rparen
      rparen_loc&.slice
    end

    # :section:

    #: (untyped other) -> boolish
    def ===(other) # :nodoc:
      other.is_a?(YieldNode) &&
        (keyword_loc.nil? == other.keyword_loc.nil?) &&
        (lparen_loc.nil? == other.lparen_loc.nil?) &&
        (arguments === other.arguments) &&
        (rparen_loc.nil? == other.rparen_loc.nil?)
    end
  end

  # Flags for arguments nodes.
  module ArgumentsNodeFlags
    # if the arguments contain forwarding
    CONTAINS_FORWARDING = 1 << 2

    # if the arguments contain keywords
    CONTAINS_KEYWORDS = 1 << 3

    # if the arguments contain a keyword splat
    CONTAINS_KEYWORD_SPLAT = 1 << 4

    # if the arguments contain a splat
    CONTAINS_SPLAT = 1 << 5

    # if the arguments contain multiple splats
    CONTAINS_MULTIPLE_SPLATS = 1 << 6
  end

  # Flags for array nodes.
  module ArrayNodeFlags
    # if array contains splat nodes
    CONTAINS_SPLAT = 1 << 2
  end

  # Flags for call nodes.
  module CallNodeFlags
    # &. operator
    SAFE_NAVIGATION = 1 << 2

    # a call that could have been a local variable
    VARIABLE_CALL = 1 << 3

    # a call that is an attribute write, so the value being written should be returned
    ATTRIBUTE_WRITE = 1 << 4

    # a call that ignores method visibility
    IGNORE_VISIBILITY = 1 << 5
  end

  # Flags for nodes that have unescaped content.
  module EncodingFlags
    # internal bytes forced the encoding to UTF-8
    FORCED_UTF8_ENCODING = 1 << 2

    # internal bytes forced the encoding to binary
    FORCED_BINARY_ENCODING = 1 << 3
  end

  # Flags for integer nodes that correspond to the base of the integer.
  module IntegerBaseFlags
    # 0b prefix
    BINARY = 1 << 2

    # 0d or no prefix
    DECIMAL = 1 << 3

    # 0o or 0 prefix
    OCTAL = 1 << 4

    # 0x prefix
    HEXADECIMAL = 1 << 5
  end

  # Flags for interpolated string nodes that indicated mutability if they are also marked as literals.
  module InterpolatedStringNodeFlags
    # frozen by virtue of a `frozen_string_literal: true` comment or `--enable-frozen-string-literal`; only for adjacent string literals like `'a' 'b'`
    FROZEN = 1 << 2

    # mutable by virtue of a `frozen_string_literal: false` comment or `--disable-frozen-string-literal`; only for adjacent string literals like `'a' 'b'`
    MUTABLE = 1 << 3
  end

  # Flags for keyword hash nodes.
  module KeywordHashNodeFlags
    # a keyword hash which only has `AssocNode` elements all with symbol keys, which means the elements can be treated as keyword arguments
    SYMBOL_KEYS = 1 << 2
  end

  # Flags for while and until loop nodes.
  module LoopFlags
    # a loop after a begin statement, so the body is executed first before the condition
    BEGIN_MODIFIER = 1 << 2
  end

  # Flags for parameter nodes.
  module ParameterFlags
    # a parameter name that has been repeated in the method signature
    REPEATED_PARAMETER = 1 << 2
  end

  # Flags for parentheses nodes.
  module ParenthesesNodeFlags
    # parentheses that contain multiple potentially void statements
    MULTIPLE_STATEMENTS = 1 << 2
  end

  # Flags for range and flip-flop nodes.
  module RangeFlags
    # ... operator
    EXCLUDE_END = 1 << 2
  end

  # Flags for regular expression and match last line nodes.
  module RegularExpressionFlags
    # i - ignores the case of characters when matching
    IGNORE_CASE = 1 << 2

    # x - ignores whitespace and allows comments in regular expressions
    EXTENDED = 1 << 3

    # m - allows $ to match the end of lines within strings
    MULTI_LINE = 1 << 4

    # o - only interpolates values into the regular expression once
    ONCE = 1 << 5

    # e - forces the EUC-JP encoding
    EUC_JP = 1 << 6

    # n - forces the ASCII-8BIT encoding
    ASCII_8BIT = 1 << 7

    # s - forces the Windows-31J encoding
    WINDOWS_31J = 1 << 8

    # u - forces the UTF-8 encoding
    UTF_8 = 1 << 9

    # internal bytes forced the encoding to UTF-8
    FORCED_UTF8_ENCODING = 1 << 10

    # internal bytes forced the encoding to binary
    FORCED_BINARY_ENCODING = 1 << 11

    # internal bytes forced the encoding to US-ASCII
    FORCED_US_ASCII_ENCODING = 1 << 12
  end

  # Flags for shareable constant nodes.
  module ShareableConstantNodeFlags
    # constant writes that should be modified with shareable constant value literal
    LITERAL = 1 << 2

    # constant writes that should be modified with shareable constant value experimental everything
    EXPERIMENTAL_EVERYTHING = 1 << 3

    # constant writes that should be modified with shareable constant value experimental copy
    EXPERIMENTAL_COPY = 1 << 4
  end

  # Flags for string nodes.
  module StringFlags
    # internal bytes forced the encoding to UTF-8
    FORCED_UTF8_ENCODING = 1 << 2

    # internal bytes forced the encoding to binary
    FORCED_BINARY_ENCODING = 1 << 3

    # frozen by virtue of a `frozen_string_literal: true` comment or `--enable-frozen-string-literal`
    FROZEN = 1 << 4

    # mutable by virtue of a `frozen_string_literal: false` comment or `--disable-frozen-string-literal`
    MUTABLE = 1 << 5
  end

  # Flags for symbol nodes.
  module SymbolFlags
    # internal bytes forced the encoding to UTF-8
    FORCED_UTF8_ENCODING = 1 << 2

    # internal bytes forced the encoding to binary
    FORCED_BINARY_ENCODING = 1 << 3

    # internal bytes forced the encoding to US-ASCII
    FORCED_US_ASCII_ENCODING = 1 << 4
  end

  # The flags that are common to all nodes.
  module NodeFlags
    # A flag to indicate that the node is a candidate to emit a :line event
    # through tracepoint when compiled.
    NEWLINE = 1

    # A flag to indicate that the value that the node represents is a value that
    # can be determined at parse-time.
    STATIC_LITERAL = 2
  end
end
